@import "tailwindcss";

@theme {
  --font-sans: 'Plus Jakarta Sans', ui-sans-serif, sans-serif;
  --font-heading: 'Space Grotesk', ui-sans-serif, sans-serif;
  --font-mono: 'JetBrains Mono', ui-monospace, monospace;

  --color-bg-primary: #0d1117;
  --color-bg-secondary: #161b22;
  --color-bg-tertiary: #21262d;
  --color-bg-overlay: #1c2128;

  --color-border-default: #30363d;
  --color-border-muted: #21262d;

  --color-text-primary: #f0f6fc;
  --color-text-secondary: #8b949e;
  --color-text-tertiary: #6e7681;

  --color-accent: #00d4aa;
  --color-accent-hover: #00e6b8;
  --color-accent-muted: rgba(0, 212, 170, 0.12);
  --color-accent-border: rgba(0, 212, 170, 0.3);

  --color-brand: #475F91;
  --color-brand-hover: #5570a8;
  --color-brand-muted: rgba(71, 95, 145, 0.15);

  --color-amber: #d2991d;
  --color-amber-muted: rgba(210, 153, 29, 0.12);
  --color-violet: #a371f7;
  --color-violet-muted: rgba(163, 113, 247, 0.12);
}

@layer base {
  * {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
  }

  html {
    scroll-behavior: smooth;
    -webkit-font-smoothing: antialiased;
    -moz-osx-font-smoothing: grayscale;
  }

  body {
    font-family: var(--font-sans);
    background-color: var(--color-bg-primary);
    color: var(--color-text-primary);
    line-height: 1.6;
    min-height: 100vh;
  }

  ::selection {
    background: rgba(0, 212, 170, 0.25);
    color: #f0f6fc;
  }

  ::-webkit-scrollbar {
    width: 8px;
    height: 8px;
  }

  ::-webkit-scrollbar-track {
    background: var(--color-bg-primary);
  }

  ::-webkit-scrollbar-thumb {
    background: var(--color-border-default);
    border-radius: 4px;
  }

  ::-webkit-scrollbar-thumb:hover {
    background: #484f58;
  }
}

@layer utilities {
  .text-gradient {
    background: linear-gradient(135deg, #00d4aa 0%, #58a6ff 100%);
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    background-clip: text;
  }

  .glass {
    background: rgba(22, 27, 34, 0.6);
    backdrop-filter: blur(16px);
    -webkit-backdrop-filter: blur(16px);
    border: 1px solid rgba(48, 54, 61, 0.5);
  }

  .glow-green {
    box-shadow: 0 0 20px rgba(0, 212, 170, 0.08), 0 0 60px rgba(0, 212, 170, 0.04);
  }

  .glow-blue {
    box-shadow: 0 0 20px rgba(71, 95, 145, 0.08), 0 0 60px rgba(71, 95, 145, 0.04);
  }

  .card-hover {
    transition: border-color 0.25s ease, box-shadow 0.25s ease, transform 0.25s ease;
  }

  .card-hover:hover {
    border-color: var(--color-accent-border);
    box-shadow: 0 0 24px rgba(0, 212, 170, 0.06);
    transform: translateY(-2px);
  }

  .noise-bg::before {
    content: '';
    position: fixed;
    inset: 0;
    background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 256 256' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='noise'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.9' numOctaves='4' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23noise)' opacity='0.02'/%3E%3C/svg%3E");
    background-repeat: repeat;
    pointer-events: none;
    z-index: 9999;
  }
}

@keyframes fade-in-up {
  from {
    opacity: 0;
    transform: translateY(24px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@keyframes fade-in {
  from { opacity: 0; }
  to { opacity: 1; }
}

@keyframes slide-in-left {
  from {
    opacity: 0;
    transform: translateX(-20px);
  }
  to {
    opacity: 1;
    transform: translateX(0);
  }
}

@keyframes pulse-glow {
  0%, 100% {
    box-shadow: 0 0 20px rgba(0, 212, 170, 0.08);
  }
  50% {
    box-shadow: 0 0 32px rgba(0, 212, 170, 0.18);
  }
}

.animate-fade-in-up {
  animation: fade-in-up 0.6s ease forwards;
}

.animate-fade-in {
  animation: fade-in 0.5s ease forwards;
}

.animate-slide-in-left {
  animation: slide-in-left 0.4s ease forwards;
}

.animate-pulse-glow {
  animation: pulse-glow 2.5s ease-in-out infinite;
}

.stagger-1 { animation-delay: 0.1s; }
.stagger-2 { animation-delay: 0.2s; }
.stagger-3 { animation-delay: 0.3s; }
.stagger-4 { animation-delay: 0.4s; }
.stagger-5 { animation-delay: 0.5s; }

