import { useState } from 'react'
import { Menu, X, Search, Moon, Sun } from 'lucide-react'
import { cn } from '@/lib/utils'

const NAV_ITEMS = [
  { label: 'Apps', href: 'apps-build.html' },
  { label: 'Storefronts', href: 'storefronts.html' },
  { label: 'Agents', href: 'agents.html' },
  { label: 'References', href: '#' },
  { label: 'Help', href: 'support.html' },
]

export function Header() {
  const [mobileOpen, setMobileOpen] = useState(false)
  const [dark, setDark] = useState(true)
  const [searchOpen, setSearchOpen] = useState(false)

  const toggleDark = () => {
    setDark(!dark)
    document.documentElement.classList.toggle('dark', !dark)
  }

  const currentPage = typeof window !== 'undefined'
    ? window.location.pathname.split('/').pop() || 'index.html'
    : 'index.html'

  return (
    <header className="sticky top-0 z-50 glass border-b border-[var(--color-border-default)]">
      <div className="mx-auto max-w-[1400px] px-6 lg:px-8">
        <div className="flex h-16 items-center justify-between">
          {/* Logo */}
          <a href="index.html" className="flex items-center gap-3 shrink-0">
            <div className="flex h-8 w-8 items-center justify-center rounded-lg bg-[var(--color-accent)]">
              <span className="font-heading text-sm font-bold text-[#0d1117]">CF</span>
            </div>
            <span className="font-heading text-lg font-semibold tracking-tight text-[var(--color-text-primary)] hidden sm:block">
              CommerceForge
            </span>
          </a>

          {/* Desktop Nav */}
          <nav className="hidden lg:flex items-center gap-1">
            {NAV_ITEMS.map((item) => {
              const isActive = currentPage === item.href ||
                (currentPage === 'index.html' && item.href === 'index.html')
              return (
                <a
                  key={item.label}
                  href={item.href}
                  className={cn(
                    'px-3 py-2 rounded-md text-sm font-medium transition-colors duration-150',
                    isActive
                      ? 'text-[var(--color-accent)] bg-[var(--color-accent-muted)]'
                      : 'text-[var(--color-text-secondary)] hover:text-[var(--color-text-primary)] hover:bg-[var(--color-bg-tertiary)]'
                  )}
                >
                  {item.label}
                </a>
              )
            })}
          </nav>

          {/* Right actions */}
          <div className="flex items-center gap-2">
            {/* Search */}
            <button
              onClick={() => setSearchOpen(!searchOpen)}
              className="flex items-center gap-2 px-3 py-2 rounded-md text-sm text-[var(--color-text-secondary)] hover:text-[var(--color-text-primary)] hover:bg-[var(--color-bg-tertiary)] transition-colors"
            >
              <Search className="h-4 w-4" />
              <span className="hidden md:inline">Ask assistant</span>
            </button>

            {/* Dark mode toggle */}
            <button
              onClick={toggleDark}
              className="p-2 rounded-md text-[var(--color-text-secondary)] hover:text-[var(--color-text-primary)] hover:bg-[var(--color-bg-tertiary)] transition-colors"
              aria-label="Toggle dark mode"
            >
              {dark ? <Sun className="h-4 w-4" /> : <Moon className="h-4 w-4" />}
            </button>

            {/* Log in */}
            <a
              href="#"
              className="hidden sm:inline-flex items-center px-4 py-2 rounded-md text-sm font-medium bg-[var(--color-bg-tertiary)] text-[var(--color-text-primary)] hover:bg-[var(--color-border-default)] transition-colors"
            >
              Log in
            </a>

            {/* Mobile menu toggle */}
            <button
              onClick={() => setMobileOpen(!mobileOpen)}
              className="lg:hidden p-2 rounded-md text-[var(--color-text-secondary)] hover:text-[var(--color-text-primary)] hover:bg-[var(--color-bg-tertiary)] transition-colors"
              aria-label="Toggle menu"
            >
              {mobileOpen ? <X className="h-5 w-5" /> : <Menu className="h-5 w-5" />}
            </button>
          </div>
        </div>

        {/* Mobile Nav */}
        {mobileOpen && (
          <nav className="lg:hidden py-4 border-t border-[var(--color-border-default)] animate-fade-in">
            <div className="flex flex-col gap-1">
              {NAV_ITEMS.map((item) => (
                <a
                  key={item.label}
                  href={item.href}
                  onClick={() => setMobileOpen(false)}
                  className="px-3 py-2.5 rounded-md text-sm font-medium text-[var(--color-text-secondary)] hover:text-[var(--color-text-primary)] hover:bg-[var(--color-bg-tertiary)] transition-colors"
                >
                  {item.label}
                </a>
              ))}
              <a
                href="#"
                className="px-3 py-2.5 rounded-md text-sm font-medium text-[var(--color-text-secondary)] hover:text-[var(--color-text-primary)] hover:bg-[var(--color-bg-tertiary)] transition-colors sm:hidden"
              >
                Log in
              </a>
            </div>
          </nav>
        )}
      </div>
    </header>
  )
}

