import { useState } from 'react'
import { ChevronLeft, ChevronRight } from 'lucide-react'
import { cn } from '@/lib/utils'

interface SidebarItem {
  id: string
  label: string
}

interface SidebarProps {
  items: SidebarItem[]
  title: string
}

export function Sidebar({ items, title }: SidebarProps) {
  const [collapsed, setCollapsed] = useState(false)
  const [activeId, setActiveId] = useState<string | null>(null)

  const handleClick = (id: string) => {
    setActiveId(id)
    const el = document.getElementById(id)
    if (el) {
      el.scrollIntoView({ behavior: 'smooth', block: 'start' })
    }
  }

  return (
    <>
      {/* Desktop sidebar */}
      <aside
        className={cn(
          'hidden lg:block sticky top-20 h-[calc(100vh-5rem)] border-r border-[var(--color-border-default)] bg-[var(--color-bg-primary)] transition-all duration-300 shrink-0',
          collapsed ? 'w-14' : 'w-60'
        )}
      >
        <div className="flex flex-col h-full">
          <div className={cn(
            'flex items-center border-b border-[var(--color-border-default)]',
            collapsed ? 'justify-center px-2 py-4' : 'justify-between px-4 py-4'
          )}>
            {!collapsed && (
              <span className="font-heading text-xs font-semibold text-[var(--color-text-secondary)] uppercase tracking-wider">
                {title}
              </span>
            )}
            <button
              onClick={() => setCollapsed(!collapsed)}
              className="p-1 rounded-md text-[var(--color-text-secondary)] hover:text-[var(--color-text-primary)] hover:bg-[var(--color-bg-tertiary)] transition-colors"
              aria-label={collapsed ? 'Expand sidebar' : 'Collapse sidebar'}
            >
              {collapsed ? <ChevronRight className="h-4 w-4" /> : <ChevronLeft className="h-4 w-4" />}
            </button>
          </div>

          <nav className="flex-1 overflow-y-auto py-2">
            {items.map((item) => (
              <button
                key={item.id}
                onClick={() => handleClick(item.id)}
                className={cn(
                  'w-full text-left transition-colors duration-150',
                  collapsed
                    ? 'px-2 py-2.5 flex justify-center'
                    : 'px-4 py-2',
                  activeId === item.id
                    ? 'text-[var(--color-accent)] bg-[var(--color-accent-muted)] border-r-2 border-[var(--color-accent)]'
                    : 'text-[var(--color-text-secondary)] hover:text-[var(--color-text-primary)] hover:bg-[var(--color-bg-tertiary)]'
                )}
                title={collapsed ? item.label : undefined}
              >
                <span className={cn('text-sm block', collapsed && 'text-[10px] text-center leading-tight')}>
                  {collapsed ? item.label.slice(0, 2).toUpperCase() : item.label}
                </span>
              </button>
            ))}
          </nav>
        </div>
      </aside>

      {/* Mobile sidebar (bottom sheet style) */}
      <div className="lg:hidden sticky top-16 z-30 bg-[var(--color-bg-primary)] border-b border-[var(--color-border-default)]">
        <div className="flex overflow-x-auto gap-1 px-4 py-2 no-scrollbar">
          {items.map((item) => (
            <button
              key={item.id}
              onClick={() => handleClick(item.id)}
              className={cn(
                'shrink-0 px-3 py-1.5 rounded-full text-xs font-medium transition-colors whitespace-nowrap',
                activeId === item.id
                  ? 'bg-[var(--color-accent)] text-[#0d1117]'
                  : 'text-[var(--color-text-secondary)] bg-[var(--color-bg-tertiary)] hover:text-[var(--color-text-primary)]'
              )}
            >
              {item.label}
            </button>
          ))}
        </div>
      </div>
    </>
  )
}

