import { readFileSync, writeFileSync, readdirSync } from 'fs';
import { join, dirname, basename } from 'path';

const distDir = '/app/commerceforge/dist';
const outDir = '/app/output';

// Read all HTML files
const htmlFiles = readdirSync(distDir).filter(f => f.endsWith('.html'));

for (const htmlFile of htmlFiles) {
  let html = readFileSync(join(distDir, htmlFile), 'utf-8');

  // Replace module script references with inline scripts
  html = html.replace(/<script type="module" crossorigin src="([^"]+)"><\/script>/g, (match, src) => {
    const filePath = join(distDir, src);
    try {
      const content = readFileSync(filePath, 'utf-8');
      return `<script type="module">${content}</script>`;
    } catch(e) {
      return match;
    }
  });

  // Replace modulepreload links (remove them since we're inlining)
  html = html.replace(/<link rel="modulepreload"[^>]*>/g, '');

  // Replace CSS link with inline style
  html = html.replace(/<link rel="stylesheet" crossorigin href="([^"]+)">/g, (match, href) => {
    const filePath = join(distDir, href);
    try {
      const content = readFileSync(filePath, 'utf-8');
      return `<style>${content}</style>`;
    } catch(e) {
      return match;
    }
  });

  writeFileSync(join(outDir, htmlFile), html);
  console.log(`Inlined: ${htmlFile}`);
}
