import { build } from 'vite'
import tailwindcss from '@tailwindcss/vite'
import { resolve } from 'path'
import { cpSync, mkdirSync, rmSync } from 'fs'

const __dirname = import.meta.dirname

const pages = [
  { name: 'main', html: 'index.html', entry: 'src/home.tsx' },
  { name: 'apps-build', html: 'apps-build.html', entry: 'src/apps-build.tsx' },
  { name: 'storefronts', html: 'storefronts.html', entry: 'src/storefronts.tsx' },
  { name: 'agents', html: 'agents.html', entry: 'src/agents.tsx' },
  { name: 'support', html: 'support.html', entry: 'src/support.tsx' },
]

const outDir = resolve(__dirname, 'dist')
rmSync(outDir, { recursive: true, force: true })
mkdirSync(outDir, { recursive: true })
mkdirSync(resolve(outDir, 'assets'), { recursive: true })

for (const page of pages) {
  const pageOutDir = resolve(__dirname, `dist-tmp/${page.name}`)
  await build({
    base: './',
    plugins: [tailwindcss()],
    resolve: {
      alias: { '@': resolve(__dirname, 'src') },
    },
    build: {
      outDir: pageOutDir,
      emptyOutDir: true,
      modulePreload: false,
      cssCodeSplit: false,
      rollupOptions: {
        input: resolve(__dirname, page.html),
        output: {
          inlineDynamicImports: true,
          entryFileNames: `assets/${page.name}-[hash].js`,
          chunkFileNames: `assets/${page.name}-chunk-[hash].js`,
          assetFileNames: `assets/${page.name}-[name]-[hash].[ext]`,
        },
      },
    },
  })
  console.log(`Built: ${page.name}`)
}

// Collect all built files into a single dist
for (const page of pages) {
  const pageOutDir = resolve(__dirname, `dist-tmp/${page.name}`)
  cpSync(pageOutDir, outDir, { recursive: true })
}
rmSync(resolve(__dirname, 'dist-tmp'), { recursive: true })

console.log('All pages built and collected into dist/')

